<?php
namespace App\Http\Controllers;
use App\Services\{StaffAccess,SalonStore,Tenant,ProviderPasswords,ProviderIdentity};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash};
final class MemberController{
 public function handle(Request $r,?string $id=null){
  abort_unless($r->session()->get('admin')===true&&!StaffAccess::editor($r)&&(int)$r->session()->get('provider_id',1)===app(Tenant::class)->id,403);$provider=app(Tenant::class)->id;
  if($r->isMethod('GET'))return response()->json(DB::table('provider_members')->where('provider_id',$provider)->get(['id','staff_id','email','role','active','created_at','updated_at']));
  $v=$r->validate(['staff_id'=>($id?'sometimes':'required_without:newStaff').'|string|max:80','newStaff'=>'sometimes|array:name,role,email,phone,description','newStaff.name'=>'required_with:newStaff|string|max:150','newStaff.role'=>'required_with:newStaff|string|max:150','newStaff.email'=>'nullable|email|max:200','newStaff.phone'=>'nullable|string|max:60','newStaff.description'=>'nullable|string|max:20000','staffProfile'=>'sometimes|array:name,role,email,phone,description','staffProfile.name'=>'required_with:staffProfile|string|max:150','staffProfile.role'=>'required_with:staffProfile|string|max:150','staffProfile.email'=>'nullable|email|max:200','staffProfile.phone'=>'nullable|string|max:60','staffProfile.description'=>'nullable|string|max:20000','email'=>($id?'sometimes':'required').'|email|max:200','password'=>($id?'nullable':'required').'|string|min:12|max:200|confirmed','role'=>'sometimes|in:editor,admin','active'=>'sometimes|boolean']);if(isset($v['email']))$v['email']=mb_strtolower(trim($v['email']));
  $result=app(SalonStore::class)->mutate(function(&$s)use($v,$id,$provider){abort_unless($s['settings']['businessMode']==='team',422,'Munkatársi belépést több munkatársas vállalkozásnál adhatsz.');\App\Services\PaidFeatures::require($s);$old=$id?DB::table('provider_members')->where('provider_id',$provider)->where('id',$id)->lockForUpdate()->first():null;abort_if($id&&!$old,404);if(isset($v['newStaff'])){abort_if($id,422);$person=$v['newStaff'];$person['id']=(string)\Illuminate\Support\Str::uuid();$person['email']=$person['email']??$v['email'];$person=\App\Services\Contact::apply($person);$person['description']=\App\Services\SafeHtml::clean($person['description']??'');\App\Services\Settings::checkCalendars($s,[...$s['staff'],$person]);$s['staff'][]=$person;$v['staff_id']=$person['id'];}$staff=$v['staff_id']??$old->staff_id;abort_unless(collect($s['staff'])->contains(fn($p)=>$p['id']===$staff&&empty($p['archived'])),422,'Válassz aktív munkatársat.');$email=$v['email']??$old->email;if(isset($v['staffProfile'])){$profile=\App\Services\Contact::apply($v['staffProfile']);$profile['description']=\App\Services\SafeHtml::clean($profile['description']??'');foreach($s['staff'] as &$person)if($person['id']===$staff)$person=array_replace($person,$profile);unset($person);}abort_if(mb_strtolower(ProviderPasswords::email($provider))===$email,422,'A tulajdonos meglévő belépéséhez nem kell munkatársi fiók.');$q=DB::table('provider_members')->where('provider_id',$provider)->where(fn($q)=>$q->where('email',$email)->orWhere('staff_id',$staff));if($id)$q->where('id','!=',$id);abort_if($q->exists(),422,'Ehhez a munkatárshoz vagy e-mail-címhez már van belépés.');$values=['staff_id'=>$staff,'email'=>$email,'role'=>$v['role']??($old->role??'editor'),'active'=>$v['active']??($old->active??true),'updated_at'=>now()];if(!empty($v['password']))$values['password_hash']=Hash::make($v['password']);if($old){$values['version']=$old->version+1;DB::table('provider_members')->where('id',$id)->update($values);DB::table('provider_password_tokens')->where('member_id',$id)->whereNull('used_at')->update(['used_at'=>now()]);}else{$id=DB::table('provider_members')->insertGetId($values+['provider_id'=>$provider,'password_hash'=>$values['password_hash'],'created_at'=>now()]);}return DB::table('provider_members')->where('id',$id)->first(['id','staff_id','email','role','active']);});return response()->json($result,$id?200:201);
 }
 public function activate(Request $r){$v=$r->validate(['memberId'=>'required|integer']);$choice=$r->session()->get('member_login_choices');abort_unless($choice&&$choice['expires']>=time()&&in_array((int)$v['memberId'],$choice['ids'],true),403);$m=DB::table('provider_members')->find($v['memberId']);abort_unless($m&&$m->active&&(int)$m->version===($choice['versions'][$m->id]??null),403);$r->session()->forget('member_login_choices');StaffAccess::signIn($r,$m);return response()->json(['id'=>(int)$m->provider_id,'url'=>'/?provider='.$m->provider_id]);}
 public static function login(Request $r,string $email,string $password):?array{
  $matches=[];foreach(DB::table('provider_members')->where('email',$email)->where('active',true)->get() as $m)if(Hash::check($password,$m->password_hash)){$exists=$m->provider_id===1||DB::table('providers')->where('id',$m->provider_id)->where('active',true)->exists();$row=$exists?DB::table('salon_state')->where('id',$m->provider_id)->value('data'):null;$s=$row?json_decode($row,true):null;if($s&&\App\Services\PaidFeatures::enabled($s)&&($m->role==='admin'||($s['settings']['businessMode']??'team')==='team')&&collect($s['staff'])->contains(fn($p)=>$p['id']===$m->staff_id&&empty($p['archived'])))$matches[]=[$m,$s['settings']['name']];}
  if(!$matches)return null;if(count($matches)===1){$m=$matches[0][0];StaffAccess::signIn($r,$m);return ['id'=>(int)$m->provider_id,'url'=>'/?provider='.$m->provider_id];}
  $r->session()->regenerate();$r->session()->put('member_login_choices',['ids'=>array_map(fn($v)=>(int)$v[0]->id,$matches),'versions'=>array_column(array_map(fn($v)=>['id'=>$v[0]->id,'version'=>(int)$v[0]->version],$matches),'version','id'),'expires'=>time()+300]);return ['workspaces'=>array_map(fn($v)=>['memberId'=>$v[0]->id,'name'=>$v[1]],$matches)];
 }
}
